<template>
  <section class="graph-view" :class="{ 'is-focused': Boolean(selectedId) }" @click.self="exitFocus">
    <header class="graph-head">
      <div><p>观星识药</p><h2>{{ title }}</h2></div>
      <div class="filters"><span>关系</span><button v-for="item in relations" :key="item" :class="{ active: relationFilters.has(item) }" @click="toggleRelation(item)">{{ item }}</button><span>实体</span><button v-for="item in entityTypes" :key="item" :class="{ active: entityFilters.has(item) }" @click="toggleEntity(item)">{{ graphVisual.entity[item].label }}</button></div>
    </header>
    <StateLoading v-if="loading" class="graph-state" size="lg" title="经络正在落星" description="正在将本草线索编入图谱。" />
    <StateError v-else-if="error" class="graph-state" size="lg" title="图谱暂时没有接上" description="稍后重试即可继续查看这张星图。" @action="emit('retry')" />
    <StateEmpty v-else-if="!content.nodes.length" class="graph-state" size="lg" title="这片药海还没画星图" description="去开一炉图谱，把药性、证候与方剂连起来。" />
    <template v-else>
      <div ref="canvasRef" class="graph-canvas" @dblclick="onCanvasDoubleClick" />
      <div class="edge-labels"><button v-for="edge in labelledEdges" :key="edge.key" :class="edge.group" :style="edge.position" @click="selectEdge(edge.edge)">{{ edge.label }}</button></div>
      <aside class="legend"><p>星链图例</p><span v-for="(style, name) in graphVisual.relation" :key="name" :class="name"><i />{{ style.group }}</span></aside>
      <div class="controls"><button title="放大" @click="zoom(.18)">+</button><button title="缩小" @click="zoom(-.18)">−</button><button title="适应画布" @click="fit">⌗</button><button title="重新布局" @click="relayout">↻</button></div>
      <Transition name="detail"><aside v-if="selectedNode" class="detail-panel"><header><div><p>{{ graphVisual.entity[selectedNode.type].label }}</p><h3>{{ selectedNode.name }}</h3><span>{{ selectedNode.brief }}</span></div><button title="关闭" @click="exitFocus">×</button></header><div v-if="detailLoading" class="detail-wait">正在查阅本草</div><template v-else><section v-for="item in detailRows" :key="item.label"><h4>{{ item.label }}</h4><p>{{ item.value }}</p></section><section v-if="detail?.关联考点"><h4>关联考点</h4><p>{{ detail.关联考点.说明 }}<b> 高频度 {{ Math.round((detail.关联考点.exam_frequency || 0) * 100) }}%</b></p></section><details v-if="detail?.sources?.length"><summary>溯源原文</summary><blockquote v-for="source in detail.sources" :key="source.出处"><b>{{ source.出处 }}</b><p>{{ source.原文摘录 }}</p><small>{{ source.定位 }}</small></blockquote></details></template></aside></Transition>
      <Transition name="source"><aside v-if="selectedEdge" class="source-popover"><button title="关闭" @click="selectedEdge = null">×</button><p>{{ selectedEdge.edge.label }}</p><span>{{ selectedEdge.edge.relation_type }}</span><blockquote><b>{{ selectedEdge.source?.出处 }}</b>{{ selectedEdge.source?.原文摘录 }}<small>{{ selectedEdge.source?.定位 }}</small></blockquote></aside></Transition>
    </template>
  </section>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Graph } from '@antv/g6'
import { graphVisual, relationStyle } from '../../config/graph'
import { StateEmpty, StateError, StateLoading } from '../state'
import { useGraphStore } from '../../stores/graph'
import type { GraphContent, GraphEdge, GraphEntityType, GraphNode } from '../../types/graph'

const props = withDefaults(defineProps<{ content: GraphContent; title?: string; loading?: boolean; error?: boolean; initialFocusId?: string }>(), { title: '中药图谱', loading: false, error: false, initialFocusId: '' })
const emit = defineEmits<{ (e: 'node-select', node: GraphNode): void; (e: 'edge-select', edge: GraphEdge): void; (e: 'expand', node: GraphNode): void; (e: 'retry'): void }>()
const graphStore = useGraphStore(); const canvasRef = ref<HTMLDivElement>(); const selectedId = ref(''); const selectedEdge = ref<{ edge: GraphEdge; source: GraphContent['sources'][number] | undefined } | null>(null)
const relationFilters = ref(new Set<string>()); const entityFilters = ref(new Set<GraphEntityType>(['herb', 'syndrome', 'formula', 'category'])); const layoutSeed = ref(0); let graph: Graph | null = null; let observer: ResizeObserver | null = null
const relations = computed(() => [...new Set(props.content.edges.map(edge => edge.relation_type))]); const entityTypes: GraphEntityType[] = ['herb', 'syndrome', 'formula', 'category']
const visible = computed(() => { const filtered = props.content.edges.filter(edge => (!relationFilters.value.size || relationFilters.value.has(edge.relation_type)) && entityFilters.value.has(props.content.nodes.find(n => n.id === edge.source)?.type || 'herb') && entityFilters.value.has(props.content.nodes.find(n => n.id === edge.target)?.type || 'herb')); const edges = props.content.nodes.length > graphVisual.maxVisibleNodes ? [...filtered].sort((a, b) => (b.confidence ?? .5) - (a.confidence ?? .5)).slice(0, graphVisual.maxVisibleNodes * 2) : filtered; const used = new Set([props.content.center_id, ...edges.flatMap(edge => [edge.source, edge.target])]); return { nodes: props.content.nodes.filter(node => used.has(node.id) && entityFilters.value.has(node.type)).slice(0, graphVisual.maxVisibleNodes), edges: edges.filter(edge => used.has(edge.source) && used.has(edge.target)) } })
const selectedNode = computed(() => props.content.nodes.find(node => node.id === selectedId.value)); const detail = computed(() => graphStore.detail); const detailLoading = computed(() => graphStore.detailLoading)
const detailRows = computed(() => { if (!detail.value) return []; const d = detail.value; return [{ label: '性味归经', value: d.性味归经 }, { label: '功效主治', value: [...(d.功效主治?.功效 || []), ...(d.功效主治?.主治 || []).map(String)].join('；') }, { label: '常用剂量与炮制', value: d.常用剂量与炮制 ? `${d.常用剂量与炮制.剂量 || ''} ${d.常用剂量与炮制.炮制 || ''}` : '' }, { label: '使用禁忌', value: d.使用禁忌?.join('；') }, { label: '经典出处', value: d.经典出处?.join(' · ') }].filter(item => item.value) as Array<{ label: string; value: string }> })
const labelledEdges = computed(() => visible.value.edges.slice(0, 14).map((edge, index) => ({ key: `${edge.source}-${edge.target}-${edge.label}`, edge, label: edge.label, group: relationStyle(edge.relation_type).group, position: { left: `${18 + ((index * 31 + layoutSeed.value * 7) % 66)}%`, top: `${23 + ((index * 19 + layoutSeed.value * 11) % 55)}%` } })))
const cssColor = (token: string): string => getComputedStyle(document.documentElement).getPropertyValue(token.match(/--[^)]+/)?.[0] || '').trim() || getComputedStyle(document.documentElement).getPropertyValue('--qh-color-jade').trim()
const render = async () => { if (!canvasRef.value || !visible.value.nodes.length) return; graph?.destroy(); const focused = selectedId.value; const neighbors = new Set(visible.value.edges.filter(edge => edge.source === focused || edge.target === focused).flatMap(edge => [edge.source, edge.target])); graph = new Graph({ container: canvasRef.value, width: canvasRef.value.clientWidth, height: canvasRef.value.clientHeight, data: { nodes: visible.value.nodes.map(node => { const entity = graphVisual.entity[node.type]; const isCenter = node.id === props.content.center_id; const active = !focused || neighbors.has(node.id); return { id: node.id, data: node, style: { x: undefined, y: undefined, size: isCenter ? 52 : 34, fill: cssColor(entity.color), stroke: cssColor(isCenter ? graphVisual.canvas.nodeStroke : graphVisual.canvas.nodeStrokeMuted), lineWidth: isCenter ? 2 : 1, fillOpacity: active ? 1 : .15, shadowColor: cssColor(entity.color), shadowBlur: isCenter ? 20 : 8, labelText: node.name, labelFill: cssColor(active ? graphVisual.canvas.labelFill : graphVisual.canvas.labelMuted), labelFontSize: isCenter ? 15 : 12, labelFontWeight: 700, labelPlacement: 'bottom', labelBackground: true, labelBackgroundFill: cssColor(graphVisual.canvas.labelBackground), labelBackgroundRadius: 3, labelPadding: [3, 5] } } }), edges: visible.value.edges.map((edge, index) => { const style = relationStyle(edge.relation_type); const active = !focused || neighbors.has(edge.source) && neighbors.has(edge.target); return { id: `e-${index}`, source: edge.source, target: edge.target, data: edge, style: { stroke: cssColor(style.color), lineWidth: 1.35, lineDash: style.dash, strokeOpacity: active ? .76 : .15, endArrow: style.arrow, halo: false } } }) }, node: { type: 'circle' }, edge: { type: 'line' }, layout: { type: 'd3-force', link: { distance: 128 }, manyBody: { strength: -340 }, collide: { radius: 46 }, alphaDecay: .08 }, behaviors: ['drag-canvas', 'zoom-canvas', 'drag-element'] } as any); graph.on('node:click', (event: any) => { const id = String(event.target?.id || event.target?.data?.id || ''); const node = visible.value.nodes.find(item => item.id === id); if (node) selectNode(node) }); graph.on('edge:click', (event: any) => { const id = String(event.target?.id || ''); const index = Number(id.replace('e-', '')); const edge = visible.value.edges[index]; if (edge) selectEdge(edge) }); await graph.render() }
const selectNode = (node: GraphNode) => { selectedEdge.value = null; selectedId.value = node.id; void graphStore.loadDetail(node.id); emit('node-select', node); void nextTick(render) }
const selectEdge = (edge: GraphEdge) => { selectedEdge.value = { edge, source: props.content.sources[edge.source_ref] }; emit('edge-select', edge) }
const exitFocus = () => { selectedId.value = ''; selectedEdge.value = null; graphStore.detail = null; void nextTick(render) }; const toggleRelation = (item: string) => { const set = new Set(relationFilters.value); set.has(item) ? set.delete(item) : set.add(item); relationFilters.value = set }; const toggleEntity = (item: GraphEntityType) => { const set = new Set(entityFilters.value); set.has(item) ? set.delete(item) : set.add(item); entityFilters.value = set }
const zoom = (delta: number) => graph?.zoomBy(delta); const fit = () => graph?.fitView(); const relayout = () => { layoutSeed.value++; void nextTick(render) }; const onCanvasDoubleClick = () => { if (selectedNode.value) emit('expand', selectedNode.value) }
onMounted(() => { void render(); observer = new ResizeObserver(() => { graph?.setSize(canvasRef.value?.clientWidth || 0, canvasRef.value?.clientHeight || 0) }); if (canvasRef.value) observer.observe(canvasRef.value); if (props.initialFocusId) { const node = props.content.nodes.find(item => item.id === props.initialFocusId); if (node) selectNode(node) } }); onBeforeUnmount(() => { observer?.disconnect(); graph?.destroy() }); watch(() => [props.content, relationFilters.value, entityFilters.value], () => void nextTick(render), { deep: true }); watch(() => props.initialFocusId, id => { const node = props.content.nodes.find(item => item.id === id); if (node) selectNode(node) })
</script>

<style scoped lang="scss">
