qh-color-gold)}.legend,.controls,.source-popover{position:absolute;border:1px solid var(--qh-color-jade-line);border-radius:var(--qh-radius-stage);background:var(--qh-color-night-glass);box-shadow:0 8px 25px var(--qh-color-shadow);backdrop-filter:blur(12px)}.legend{bottom:18px;left:18px;display:grid;gap:5px;padding:10px}.legend span{color:var(--qh-text-muted);font-size:11px}.legend i{display:inline-block;width:18px;margin-right:6px;border-top:2px solid var(--qh-color-jade);vertical-align:middle}.legend .鉴别 i{border-color:var(--qh-color-coral);border-top-style:dashed}.legend .药证方链 i{border-color:var(--qh-color-gold)}.legend .聚类 i{border-color:var(--qh-color-cream-line);border-top-style:dotted}.controls{right:18px;bottom:18px;display:flex;overflow:hidden}.controls button,.detail-panel header button,.source-popover button{width:31px;border:0;border-right:1px solid var(--qh-border);background:transparent;color:var(--qh-text);font-size:18px;cursor:pointer}.controls button:hover{background:var(--qh-color-jade-wash)}.detail-panel{position:absolute;z-index:4;top:0;right:0;width:min(360px,88vw);height:100%;overflow:auto;border-left:1px solid var(--qh-color-jade-line);background:linear-gradient(150deg,var(--qh-color-night-raised),var(--qh-color-night-overlay));padding:22px;box-sizing:border-box;box-shadow:-18px 0 48px var(--qh-color-shadow);backdrop-filter:blur(20px)}.detail-panel header{display:flex;justify-content:space-between;gap:10px;padding-bottom:17px;border-bottom:1px solid var(--qh-border)}.detail-panel h3{margin:0;color:var(--qh-color-cream);font-size:28px}.detail-panel header span,.detail-panel p{color:var(--qh-text-muted);font-size:13px;line-height:1.7}.detail-panel section{padding:12px 0;border-bottom:1px solid var(--qh-color-text-faint)}.detail-panel h4{margin:0;color:var(--qh-color-jade);font-size:12px}.detail-panel p{margin:5px 0 0}.detail-panel b{display:block;margin-top:5px;color:var(--qh-color-gold);font-size:11px}.detail-panel details{margin-top:15px;color:var(--qh-color-gold);font-size:13px}.detail-panel blockquote,.source-popover blockquote{margin:10px 0;padding-left:10px;border-left:2px solid var(--qh-color-gold);color:var(--qh-text-muted);font-size:12px;line-height:1.65}.detail-panel blockquote b,.source-popover b{display:block;color:var(--qh-color-cream)}.detail-panel small,.source-popover small{display:block;color:var(--qh-color-jade-d)}.source-popover{z-index:5;right:385px;bottom:26px;width:270px;padding:13px}.source-popover button{position:absolute;top:5px;right:3px;border:0}.source-popover p{margin:0;color:var(--qh-color-cream);font-weight:800}.source-popover span{color:var(--qh-color-coral);font-size:11px}.detail-enter-active,.detail-leave-active{transition:transform var(--qh-duration-md) ease,opacity var(--qh-duration-md) ease}.detail-enter-from,.detail-leave-to{opacity:0;transform:translateX(100%)}.source-enter-active,.source-leave-active{transition:opacity var(--qh-duration-fast)}.source-enter-from,.source-leave-to{opacity:0}@media(max-width:800px){.graph-view,.graph-canvas,.graph-state{min-height:620px}.graph-head{display:block}.filters{max-width:100%;justify-content:flex-start;margin-top:10px}.legend{display:none}.source-popover{right:14px;bottom:65px}.edge-labels button:nth-child(n+8){display:none}}.edge-labels button{position:absolute;max-width:124px;overflow:hidden;border:1px solid var(--qh-color-cream-line);border-radius:var(--qh-radius-stage);background:var(--qh-color-night-overlay);padding:3px 5px;color:var(--qh-color-text-soft);font-size:10px;line-height:1.15;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}.edge-labels button:hover{border-color:var(--qh-color-cream);background:var(--qh-color-night-raised)}
</style>
